  function spTodayParts(){var ps=new Intl.DateTimeFormat('en-CA',{timeZone:'America/Sao_Paulo',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date()),o={};ps.forEach(function(p){o[p.type]=p.value;});return o;}
  function countdown(v){if(!v)return 'Data ainda não definida';var m=String(v).match(/^(\d{4})-(\d{2})-(\d{2})/);if(!m)return 'Data a confirmar';var p=spTodayParts(),a=Date.UTC(+m[1],+m[2]-1,+m[3]),b=Date.UTC(+p.year,+p.month-1,+p.day),days=Math.round((a-b)/86400000);if(days<0)return 'Realizado há '+num(Math.abs(days))+' dia(s)';if(days===0)return 'É hoje';if(days===1)return 'Falta 1 dia';return 'Faltam '+num(days)+' dias';}
