    var p=S.importPayload,report=S.importReport,work=S.workspace;
    var progress=S.importBusy?'<div class="import-progress" aria-live="polite"><div><span>'+esc(S.importStatus||'Preparando gravação…')+'</span><b>'+Number(S.progress||0)+'%</b></div><div class="progress"><span style="width:'+Number(S.progress||0)+'%"></span></div></div>':'';
    var stepNames=['Enviar','Conferir colunas','Simulação','Confirmar'];
    var steps='<ol class="wizard-steps">'+stepNames.map(function(n,i){return '<li class="'+(S.importStep===i+1?'current':S.importStep>i+1?'done':'')+'"><span>'+(i+1)+'</span>'+n+'</li>';}).join('')+'</ol>';
    var body='';
