    if(S.importStep===2&&p){body='<div class="notice">O sistema reconhece as abas <b>Batismo</b>, <b>Ordem</b> e <b>GERAL</b>. GERAL fica em um arquivo de consulta separado e somente leitura.</div><div class="table-scroll"><table class="history-table"><thead><tr><th>Aba</th><th>Linhas</th><th>Colunas identificadas</th><th>Amostra do cabeçalho</th></tr></thead><tbody>'+p.sheetStats.map(function(s){return '<tr><td>'+esc(s.name)+'</td><td>'+num(s.rowCount)+'</td><td>'+num(s.columns)+'</td><td>'+esc(((p.rawSheets[s.name]||[])[0]||[]).slice(0,12).join(' · '))+'</td></tr>';}).join('')+'</tbody></table></div><p class="muted">Confira se os nomes das colunas e as abas estão corretos antes de continuar.</p>';}
