    if(S.importStep===4&&p){body='<div class="field-grid"><label>Modo de importação<select id="import-mode"><option value="merge"'+(S.importMode==='merge'?' selected':'')+'>Adicionar e atualizar · nunca apaga</option><option value="replace"'+(S.importMode==='replace'?' selected':'')+'>Substituir a base ativa</option></select></label>'+ (S.importMode==='replace'?'<label>Digite CONFIRMAR<input id="replace-confirm" autocomplete="off" spellcheck="false" placeholder="CONFIRMAR" value="'+esc(S.replaceText||'')+'"></label>':'')+'</div><div class="notice">Antes de gravar, será baixado um backup JSON do estado atual. A cópia Excel não fica guardada no navegador. A opção substituir troca a versão ativa e preserva as versões anteriores no Firebase.</div>'+(S.importDone?'<div class="success-panel">'+esc(S.importDone.message)+' <button type="button" class="btn secondary" data-report-download>Baixar relatório</button></div>':'');}
    root.innerHTML='<div class="page-head"><div><p class="eyebrow">SOMENTE ADMIN</p><h1>Importar</h1><p class="muted">Atualize a base com conferência e cópia de segurança.</p></div></div><div class="card"><div class="summary-strip"><span>Dados atuais no Firebase</span><strong>'+(work?num((work.people||[]).length)+' pessoas · '+num((work.order||[]).length)+' posições · '+num((work.generalAll||[]).length)+' registros GERAL':'Nenhuma versão carregada')+'</strong></div>'+steps+progress+(S.importError?'<div class="error-panel" role="alert">'+esc(S.importError)+'</div>':'')+'<div class="wizard-content">'+body+'</div><div class="wizard-actions">'+(S.importStep>1&&!S.importBusy?'<button class="btn secondary" type="button" data-import-back>Voltar</button>':'')+(S.importStep===2?'<button class="btn primary" type="button" data-import-next="3">Simular importação</button>':'')+(S.importStep===3?'<label class="mode-inline">Modo<select id="import-mode"><option value="merge"'+(S.importMode==='merge'?' selected':'')+'>Adicionar e atualizar</option><option value="replace"'+(S.importMode==='replace'?' selected':'')+'>Substituir tudo</option></select></label><button class="btn primary" type="button" data-import-next="4">Revisar confirmação</button>':'')+(S.importStep===4?'<button class="btn primary" type="button" data-import-confirm '+(S.importBusy||S.importMode==='replace'&&S.replaceText!=='CONFIRMAR'?'disabled':'')+'>Confirmar gravação</button>':'')+'</div></div><div class="card"><h2>Resumo das importações</h2><p class="muted">As gravações anteriores ficam preservadas como versões no Firestore. Esta tela não guarda o arquivo Excel.</p><div id="import-final-report">'+(S.importDone?esc(S.importDone.message):'Nenhuma importação concluída nesta sessão.')+'</div></div>';
