  function simCard(label,value,foot){return '<div class="card sim-card"><span>'+esc(label)+'</span><strong>'+num(value)+'</strong><small>'+esc(foot)+'</small></div>';}
  function mappedKey(arr,key){return new Map(arr.map(function(x,i){return [String(x&&x.sourceRow||i+2),x];}));}
  function mergeCells(a,b){var out=(a||[]).slice(),incoming=b||[];for(var i=0;i<incoming.length;i++){if(incoming[i]!==null&&incoming[i]!==undefined&&String(incoming[i]).trim()!=='')out[i]=incoming[i];}return out;}
  function mergeRecords(oldRows,newRows){var map=mappedKey(oldRows||[],'sourceRow'),out=(oldRows||[]).map(function(x){return Object.assign({},x,{fields:Array.isArray(x.fields)?x.fields.slice():x.fields});}),idx=new Map(out.map(function(x,i){return [String(x.sourceRow),i];}));(newRows||[]).forEach(function(n){var k=String(n.sourceRow);if(idx.has(k)){var i=idx.get(k),o=out[i],fields=mergeCells(o.fields,n.fields);out[i]=Object.assign({},o,n,{fields:fields});if(fields.length>=14&&('age'in n||'name'in n)){var f=fields;out[i]=Object.assign(out[i],{name:f[0]||o.name||'',age:f[1]||o.age,phone:f[2]||o.phone,turma:f[3]||o.turma,date:f[4]||o.date,journey:f[5]||o.journey,lesson:f[6]||o.lesson,group:f[7]||o.group,shirt:f[8]||o.shirt,shirtPaid:f[9]||o.shirtPaid,status:f[10]||o.status,pending:f[11]||o.pending,baptized:f[12]||o.baptized,profile:f[13]||o.profile});}}else{idx.set(k,out.length);out.push(n);}});return out;}
  function mergeRows(a,b){var out=(a||[]).map(function(r){return (r||[]).slice();}),inc=b||[];for(var i=0;i<inc.length;i++){if(!out[i])out[i]=[];out[i]=mergeCells(out[i],inc[i]);}return out;}
  function combineWorkspace(current,incoming,mode){if(mode==='replace')return Object.assign({},incoming,{sourceWorkbook:null});var old=current||{},next=Object.assign({},old,incoming,{sourceWorkbook:null});['people','order','generalAll'].forEach(function(k){next[k]=mergeRecords(old[k]||[],incoming[k]||[]);});next.order35=old.order35||[];next.general=next.generalAll.filter(function(p){return !!p.name;});next.generalUnmapped=next.generalAll.filter(function(p){return !p.name;});next.rawSheets=Object.assign({},old.rawSheets||{});Object.keys(incoming.rawSheets||{}).forEach(function(k){next.rawSheets[k]=mergeRows((old.rawSheets||{})[k],incoming.rawSheets[k]);});next.importedAt=incoming.importedAt;next.sourceFileName=incoming.sourceFileName;next.sourceFileSize=incoming.sourceFileSize;return next;}
  function simulate(payload){var current=S.workspace||{},oldPeople=mappedKey(current.people||[]),oldOrder=mappedKey(current.order||[]),added=0,updated=0,dups={},details=[],badDates=0,badPhones=0,noName=0;payload.people.forEach(function(p){if(oldPeople.has(String(p.sourceRow)))updated++;else added++;if(!p.name)noName++;var key=norm(p.name)+'|'+norm(p.turma);if(p.name){dups[key]=(dups[key]||0)+1;}if(p.date!==null&&p.date!==undefined&&String(p.date).trim()!==''&&!plausibleDate(p.date))badDates++;var d=digits(p.phone);if(d&&![10,11,12,13].includes(d.length))badPhones++;});payload.order.forEach(function(p){if(oldOrder.has(String(p.sourceRow)))updated++;else added++;});var duplicateKeys=Object.keys(dups).filter(function(k){return dups[k]>1;});duplicateKeys.slice(0,15).forEach(function(k){details.push('Possível nome repetido: '+k.split('|')[0]+' (turma '+k.split('|')[1]+')');});badDates&&details.push(badDates+' data(s) precisam de conferência.');badPhones&&details.push(badPhones+' telefone(s) com quantidade de dígitos fora do padrão.');noName&&details.push(noName+' linha(s) sem nome serão preservadas.');var blockers=[];if(!payload.rawSheets||!Object.keys(payload.rawSheets).some(function(k){return norm(k)==='batismo';}))blockers.push('A aba Batismo não foi reconhecida.');if(!Object.keys(payload.rawSheets||{}).some(function(k){return norm(k)==='ordem';}))blockers.push('A aba Ordem não foi reconhecida.');return {added:added,updated:updated,noName:noName,duplicates:duplicateKeys.length,badDates:badDates,badPhones:badPhones,details:details,blockers:blockers};}
  function plausibleDate(v){if(v instanceof Date)return !isNaN(v.getTime())&&v.getFullYear()>1900&&v.getFullYear()<2200;if(typeof v==='number')return v>20000&&v<120000;if(/^\d{1,2}[\/.-]\d{1,2}[\/.-]\d{4}$/.test(String(v))){var a=String(v).split(/[\/.-]/).map(Number);var d=new Date(a[2],a[1]-1,a[0]);return d.getFullYear()===a[2]&&d.getMonth()===a[1]-1&&d.getDate()===a[0];}var date=new Date(v);return !isNaN(date.getTime())&&date.getFullYear()>1900&&date.getFullYear()<2200;}
